/**
 * Add a hook allowing extensions to register a hook on the batch export process
 *
 * @since  0.9.5
 * @return void
 */
function intercessor_register_batch_exporters() {
	if ( is_admin() ) {
		do_action( 'intercessor_register_batch_exporter' );
	}
}
add_action( 'plugins_loaded', 'intercessor_register_batch_exporters', 99 );

